using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Default options with reflection-based resolver — knows about any public type.
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver(),
    WriteIndented    = true
};

// ── 1. Strongly-typed retrieval: GetTypeInfo<T>() ──────────────────────
//    Returns JsonTypeInfo<T> directly — no cast needed.
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Got typed metadata  : {personInfo.Type.Name}  (JsonTypeInfo<{personInfo.Type.Name}>)");

string json = JsonSerializer.Serialize(new Person("Ada", 36), personInfo);
Console.WriteLine($"Serialized with it  : {json}");

// ── 2. Probe without throwing: TryGetTypeInfo() ────────────────────────
//    Returns false instead of throwing when the type isn't resolvable.
if (options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? found))
    Console.WriteLine($"\nTryGetTypeInfo(Person)   → found   ({found!.Type.Name})");
else
    Console.WriteLine("\nTryGetTypeInfo(Person)   → not found");

// Use a resolver that knows about *nothing* to show the "not found" branch.
var empty = new JsonSerializerOptions
{
    TypeInfoResolver = new EmptyResolver()
};

if (empty.TryGetTypeInfo(typeof(Person), out _))
    Console.WriteLine("TryGetTypeInfo(Person)   → found");
else
    Console.WriteLine("TryGetTypeInfo(Person)   → not found  (empty resolver)");

// ── Types ──────────────────────────────────────────────────────────────
record Person(string Name, int Age);

// A resolver that never resolves anything.
sealed class EmptyResolver : IJsonTypeInfoResolver
{
    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options) => null;
}

